-- Grand Mall: ডাটাবেস + সব দোকান ও পণ্যের ডেটা (XAMPP phpMyAdmin > Import)
SET NAMES utf8mb4;
CREATE DATABASE IF NOT EXISTS grand_mall CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE grand_mall;
SET FOREIGN_KEY_CHECKS=0;
DROP TABLE IF EXISTS products;
DROP TABLE IF EXISTS shops;
SET FOREIGN_KEY_CHECKS=1;
CREATE TABLE shops (
  id VARCHAR(64) NOT NULL PRIMARY KEY, name VARCHAR(64) NOT NULL, subtitle VARCHAR(64) NOT NULL DEFAULT '',
  x DOUBLE NOT NULL DEFAULT 0, z DOUBLE NOT NULL DEFAULT 0, accent INT UNSIGNED NOT NULL DEFAULT 2450411,
  style VARCHAR(16) NOT NULL DEFAULT 'market', sort_order INT NOT NULL DEFAULT 0, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE products (
  id VARCHAR(160) NOT NULL PRIMARY KEY, shop_id VARCHAR(64) NOT NULL, name VARCHAR(120) NOT NULL, price DECIMAL(12,2) NOT NULL,
  image MEDIUMTEXT NULL, kind VARCHAR(24) NOT NULL DEFAULT 'box', color INT UNSIGNED NOT NULL DEFAULT 3355443, sort_order INT NOT NULL DEFAULT 0,
  KEY idx_shop (shop_id, sort_order),
  CONSTRAINT fk_products_shop FOREIGN KEY (shop_id) REFERENCES shops(id) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
